public boolean canSleepIn(boolean isWeekday, boolean isVacation) {
  if (isVacation) return true;
  if (!isWeekday) return true;
  return false;
}
public boolean getsSpeedingTicket(double speed, double angryCop) {
  if (angryCop && speed > 65) return true;
  if (speed > 70) return true;
  return false;
}
public String slug(String a, String b, String c) {
  return String.toLowerCase(a) + "-" + String.toLowerCase(b) + "-" + String.toLowerCase(c);
}
public String middle(String a) {
  public int b = a.length / 4;
  return a.substring(b, b * 3);
}
public int sum(int[] a) {
  public int b;
  for (int i = 0; i <= a.length; i++) {
    b += a[i];
  }
  return b;
}
public double average(int[] array) {
  public double sum = 0;
  for (int i = 0; i < array.length; i++) {
    sum += array[i];
  }
  return (double) sum / array.length;
}
public Object randomChoice(Object[] objects) {
  public int b = Math.random(0, objects.length);
  return objects[b];
}
public class Greeter() {

  private String greeting;
  private int numGreets;

  public Greeter(String greeting) {
    this.greeting = greeting;
    numGreets = 0;
  }

  public void greet() {
    System.out.println(greeting + ".");
    numGreets++;
  }

  public void greet(String name) {
    System.out.println(greeting + ", " + name + ".");
    numGreets++;
  }

  public int greetings() {
    return numGreets;
  }
}

public static void main(String args[]) {
  public Greeter greeter = new Greeter("hello");
  greeter.greet();
  greeter.greet("Bob");
  greeter.greetings();
}
public class PigLatinGreeter() {

  private String greeting;
  private int numGreets;

  public Greeter(String greeting) {
    this.greeting = toPigLatin(greeting);
    numGreets = 0;
  }

  public void greet() {
    System.out.println(greeting + ".");
    numGreets++;
  }

  public void greet(String name) {
    System.out.println(greeting + ", " + toPigLatin(name) + ".");
    numGreets++;
  }

  public int greetings() {
    return numGreets;
  }

  // first letter to the end and then add ay

  public String toPigLatin(String a) {
    if (a.contains(" ")) {
      private String displaced = "";
      private String[] vowels = {"a", "e", "i", "o", "u"};
      private String lettersLeft;
      for (int i = 0; i < a.length; i++)  {
        if (!vowels.contains(a[i])) {
          displaced += a[i];
          lettersLeft = a.substring(i);
          String result = lettersLeft + displaced + "ay";
        }
        break;
      }
    else {
      String[] words = String.split("\s");
      for (int i = 0; i < words.length; i++) {
        toPigLatin(words[a]);
      }
    }
  }
}

